-- Table structure for `discount_coupons`
DROP TABLE IF EXISTS `discount_coupons`;
CREATE TABLE `discount_coupons` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `seller_id` bigint(20) unsigned NOT NULL,
  `coupon_code` varchar(255) NOT NULL,
  `discount_type` varchar(255) NOT NULL DEFAULT 'percentage',
  `discount_value` decimal(10,2) NOT NULL DEFAULT 10.00,
  `min_order_amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `applicable_to` varchar(255) NOT NULL DEFAULT 'all',
  `usage_limit` int(11) NOT NULL DEFAULT 100,
  `used_count` int(11) NOT NULL DEFAULT 0,
  `valid_from` date NOT NULL,
