  PRIMARY KEY (`id`),
  KEY `seller_business_details_seller_id_foreign` (`seller_id`),
  CONSTRAINT `seller_business_details_seller_id_foreign` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`) ON DELETE CASCADE
