-- Table structure for `services`
DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `seller_id` bigint(20) unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `category` varchar(255) NOT NULL DEFAULT 'Graphic Design',
  `short_description` text DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `tags` varchar(255) DEFAULT NULL,
  `delivery_days` int(11) NOT NULL DEFAULT 3,
  `package_name` varchar(255) NOT NULL DEFAULT 'Basic',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `package_features` text DEFAULT NULL,
  `buyer_requirements` text DEFAULT NULL,
  `thumbnail` varchar(255) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'pending',
  `rejection_reason` text DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `approved_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `services_seller_id_foreign` (`seller_id`),
  KEY `services_approved_by_foreign` (`approved_by`),
  CONSTRAINT `services_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `services_seller_id_foreign` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

